RefStlScript.STL_PreparationScript:
DECLARE @UstEvent CHAR(3) = 'UST'; DECLARE @DayAsDate DATE = DATEFROMPARTS(YEAR(@EndDateTimeExclusive), MONTH(@EndDateTimeExclusive), DAY(@EndDateTimeExclusive));
DECLARE @ActiveStaffPerDay TABLE ( DayAsDate date not null, Period int not null, StaffCode varchar(3) not null);
WITH CurrentStaffCte AS ( SELECT GS_PK, GS_Code, GS_IsActive, GS_IsDevice, GS_CanLogin, GS_IsRobot FROM dbo.GlbStaff gs WHERE gs.GS_IsResource = 0 AND gs.GS_IsSystemAccount = 0 ), RankedUstLogCte AS ( SELECT staff.GS_Code, ustLog.SL_Reference, LogSequence = ROW_NUMBER() OVER(PARTITION BY ustLog.SL_Parent ORDER BY ustLog.SL_PostedTimeUtc) FROM dbo.StmALog ustLog INNER JOIN CurrentStaffCte staff ON staff.GS_PK = ustLog.SL_Parent WHERE ustLog.SL_PostedTimeUtc >= @EndDateTimeExclusive AND ustLog.SL_PostedTimeUtc <= GETUTCDATE() AND ustLog.SL_SE_NKEvent = @UstEvent ) INSERT @ActiveStaffPerDay -- Add staff with UserSeat events within date range where Reference like ('___>>%' or '%>>___') SELECT @DayAsDate, (DATEPART(year, @DayAsDate) * 100) + DATEPART(month, @DayAsDate), staff.GS_Code FROM dbo.StmALog ustLog INNER JOIN CurrentStaffCte staff ON staff.GS_PK = ustLog.SL_Parent WHERE ustLog.SL_PostedTimeUtc >= @StartDateTimeInclusive AND ustLog.SL_PostedTimeUtc < @EndDateTimeExclusive AND ustLog.SL_SE_NKEvent = @UstEvent AND ustLog.SL_Reference like '%DOU%' UNION -- Add staff who first UST event after date range has a Reference value like '___>>%' SELECT @DayAsDate, (DATEPART(year, @DayAsDate) * 100) + DATEPART(month, @DayAsDate), staff.GS_Code FROM CurrentStaffCte staff INNER JOIN RankedUstLogCte rankedUst ON staff.GS_Code = rankedUst.GS_Code WHERE rankedUst.LogSequence = 1 AND rankedUst.SL_Reference like 'DOU%' UNION -- Add staff with no UST events after date range and whose current flags match the staff status (IsActive=1, IsDevice=?, CanLogin=?) SELECT @DayAsDate, (DATEPART(year, @DayAsDate) * 100) + DATEPART(month, @DayAsDate), staff.GS_Code FROM CurrentStaffCte staff LEFT JOIN RankedUstLogCte rankedUst ON staff.GS_Code = rankedUst.GS_Code WHERE rankedUst.LogSequence is null AND staff.GS_IsActive = 1 AND staff.GS_IsDevice = 1 AND staff.GS_IsRobot = 0 AND staff.GS_CanLogin = 1 ;
